use axum::{
    extract::{Request, State},
    middleware::Next,
    response::Response,
};
use base64::Engine;
use serde::Deserialize;
use std::time::{Duration, Instant};

use super::claims;
use crate::{error::AppError, AppState};

/// Axum middleware that validates the X-Api-Key header.
pub async fn require_api_key(
    State(state): State<AppState>,
    mut req: Request,
    next: Next,
) -> Result<Response, AppError> {
    if !state.auth.auth_enabled {
        return Ok(next.run(req).await);
    }

    let api_key = req
        .headers()
        .get("Authorization")
        .and_then(|v| v.to_str().ok())
        .ok_or_else(|| AppError::Unauthorized("Missing Authorization header".into()))?;

    let validated_claims = exchange_api_key(&state, api_key).await?;

    req.extensions_mut().insert(validated_claims);
    Ok(next.run(req).await)
}

/// Decode the API key and exchange it for a validated JWT.
/// Accepts both `ApiKey <base64>` (Smithy SDK format) and raw `<base64>` (curl).
async fn exchange_api_key(state: &AppState, api_key: &str) -> Result<claims::Claims, AppError> {
    let key_value = api_key.strip_prefix("ApiKey ").unwrap_or(api_key);
    let decoded = base64::engine::general_purpose::STANDARD
        .decode(key_value)
        .map_err(|_| AppError::Unauthorized("Invalid API key encoding".into()))?;
    let decoded_str =
        String::from_utf8(decoded).map_err(|_| AppError::Unauthorized("Invalid API key".into()))?;
    let (client_id, client_secret) = decoded_str
        .split_once(':')
        .ok_or_else(|| AppError::Unauthorized("Invalid API key format".into()))?;

    // Check token cache
    let cache_key = client_id.to_string();
    if let Some(cached) = state.auth.token_cache.get(&cache_key) {
        if cached.expires_at > Instant::now() + Duration::from_secs(30) {
            return Ok(cached.claims.clone());
        }
    }

    // Exchange client credentials at the OIDC token endpoint
    let token_response =
        exchange_client_credentials(&state.auth.token_endpoint, client_id, client_secret).await?;

    // Validate the JWT
    let validated_claims = claims::validate_jwt(
        &token_response.access_token,
        &state.auth.jwks,
        &state.auth.issuer,
    )
    .await
    .map_err(AppError::Unauthorized)?;

    // Cache it
    let expires_at = Instant::now() + Duration::from_secs(token_response.expires_in);
    state.auth.token_cache.insert(
        cache_key,
        crate::CachedToken {
            access_token: token_response.access_token,
            claims: validated_claims.clone(),
            expires_at,
        },
    );

    Ok(validated_claims)
}

#[derive(Deserialize)]
struct TokenResponse {
    access_token: String,
    expires_in: u64,
}

async fn exchange_client_credentials(
    token_url: &str,
    client_id: &str,
    client_secret: &str,
) -> Result<TokenResponse, AppError> {
    let client = reqwest::Client::new();
    let resp = client
        .post(token_url)
        .form(&[
            ("grant_type", "client_credentials"),
            ("client_id", client_id),
            ("client_secret", client_secret),
        ])
        .send()
        .await
        .map_err(|e| AppError::Unauthorized(format!("Token exchange failed: {e}")))?;

    if !resp.status().is_success() {
        return Err(AppError::Unauthorized("Invalid API credentials".into()));
    }

    resp.json::<TokenResponse>()
        .await
        .map_err(|e| AppError::Unauthorized(format!("Invalid token response: {e}")))
}

use axum::extract::State;
use axum::Json;

use crate::api::dto::{ListTransactionsQuery, ListTransactionsResponse};
use crate::error::AppError;
use crate::AppState;

pub async fn list_all_transactions(
    State(state): State<AppState>,
    axum::extract::Query(query): axum::extract::Query<ListTransactionsQuery>,
) -> Result<Json<ListTransactionsResponse>, AppError> {
    let offset = query.offset.unwrap_or(0).max(0);
    let limit = query.limit.unwrap_or(20).clamp(1, 100);

    let transactions = state
        .transaction_repo
        .list_all(offset, limit, query.from_date, query.to_date, None)
        .await?;
    let total = state
        .transaction_repo
        .count_all(query.from_date, query.to_date, None)
        .await?;

    Ok(Json(ListTransactionsResponse {
        transactions: transactions.into_iter().map(|t| t.into()).collect(),
        total,
        offset,
        limit,
    }))
}

use cucumber::{then, when};
use std::time::Duration;
use tokio::time::sleep;

use crate::UiWorld;

async fn current_page_content(world: &mut UiWorld) -> String {
    let page = world.ensure_page().await;
    page.content().await.expect("Failed to read page content")
}

/// Navigate to the all-transactions list and click the timestamp link of the
/// first row, which leads to /admin/transactions/{id}.
async fn open_first_transaction_detail(world: &mut UiWorld) {
    let url = world.url("/admin/transactions");
    let page = world.ensure_page().await;
    page.goto(url)
        .await
        .expect("Failed to navigate to transactions list");
    sleep(Duration::from_millis(400)).await;

    let page = world.ensure_page().await;
    let js = r#"
        (() => {
            const links = Array.from(document.querySelectorAll("a[href*='/admin/transactions/']"));
            const detail = links.find(a => /\/admin\/transactions\/[0-9a-f-]{36}$/.test(a.getAttribute('href')));
            if (!detail) throw new Error('no detail link found on transactions list');
            detail.click();
        })();
    "#;
    page.evaluate(js)
        .await
        .expect("Failed to click first transaction detail link");
    sleep(Duration::from_millis(600)).await;
}

#[when("I view the most recent transaction's detail page")]
async fn when_view_most_recent_detail(world: &mut UiWorld) {
    open_first_transaction_detail(world).await;
}

#[then("the transaction detail should show the transaction ID")]
async fn then_show_transaction_id(world: &mut UiWorld) {
    let content = current_page_content(world).await;
    assert!(
        content.contains("Transaction ID:"),
        "expected `Transaction ID:` label on detail page, got snippet: {}",
        &content[..content.len().min(500)]
    );
}

#[then("the transaction detail should show the account ID")]
async fn then_show_account_id(world: &mut UiWorld) {
    let account_id = world
        .account_id
        .clone()
        .expect("No account ID on world for assertion");
    let content = current_page_content(world).await;
    assert!(
        content.contains(&account_id),
        "expected account ID `{}` on detail page",
        account_id
    );
}

#[then(regex = r#"^the transaction detail should show amount "([^"]*)"$"#)]
async fn then_show_amount(world: &mut UiWorld, expected: String) {
    let content = current_page_content(world).await;
    let needle = format!("₹{}", expected);
    assert!(
        content.contains(&needle),
        "expected amount `{}` on detail page",
        needle
    );
}

#[then(regex = r#"^the transaction detail should show type "([^"]*)"$"#)]
async fn then_show_type(world: &mut UiWorld, expected: String) {
    let content = current_page_content(world).await;
    let marker = "Type:</strong>";
    let idx = content
        .find(marker)
        .unwrap_or_else(|| panic!("`Type:` label not found on detail page"));
    let after = &content[idx + marker.len()..];
    let snippet = &after[..after.len().min(200)];
    assert!(
        snippet.contains(&expected),
        "expected type `{}` on detail page, after-Type snippet: {}",
        expected,
        snippet
    );
}

#[then(regex = r#"^the transaction detail should show gateway ref "([^"]*)"$"#)]
async fn then_show_gateway_ref(world: &mut UiWorld, expected: String) {
    let content = current_page_content(world).await;
    let marker = "Gateway Ref:</strong>";
    let idx = content
        .find(marker)
        .unwrap_or_else(|| panic!("`Gateway Ref:` label not found on detail page"));
    let after = &content[idx + marker.len()..];
    let snippet = &after[..after.len().min(200)];
    assert!(
        snippet.contains(&expected),
        "expected gateway ref `{}` after Gateway Ref label, got snippet: {}",
        expected,
        snippet
    );
}

#[cucumber::given(regex = r"^the account has a pending deposit of (\d+) in the self-pool$")]
async fn given_pending_self_deposit(world: &mut UiWorld, amount: i64) {
    let origin_ifsc = world.origin_ifsc.clone().expect("origin IFSC missing");
    let origin_acct = world
        .origin_account_number
        .clone()
        .expect("origin account number missing");
    crate::ui_steps::deposit_steps::create_pending_deposit_for_test(
        world,
        amount,
        &origin_ifsc,
        &origin_acct,
    )
    .await;
}

#[when("I view that pending deposit's detail page")]
async fn when_view_pending_deposit_detail(world: &mut UiWorld) {
    let deposit_id = world
        .last_deposit_id
        .clone()
        .expect("no pending deposit id on world");
    let url = world.url(&format!("/admin/transactions/{}", deposit_id));
    let page = world.ensure_page().await;
    page.goto(url)
        .await
        .expect("Failed to navigate to transaction detail");
    sleep(Duration::from_millis(500)).await;
}

#[when("I click the Post button")]
async fn when_click_post_button(world: &mut UiWorld) {
    let page = world.ensure_page().await;
    let js = r#"
        (() => {
            const form = document.querySelector("form[action$='/post']");
            if (!form) throw new Error('Post form not found on detail page');
            form.submit();
        })();
    "#;
    page.evaluate(js).await.expect("Failed to click Post");
    sleep(Duration::from_millis(800)).await;
}

#[then(regex = r#"^the transaction detail status should be "([^"]*)"$"#)]
async fn then_detail_status(world: &mut UiWorld, expected: String) {
    let content = current_page_content(world).await;
    let marker = "Status:</strong>";
    let idx = content
        .find(marker)
        .unwrap_or_else(|| panic!("`Status:` label not found on detail page"));
    let after = &content[idx + marker.len()..];
    if let Some(span_start) = after.find("<span") {
        let span = &after[span_start..];
        if let Some(gt) = span.find('>') {
            let inner = &span[gt + 1..];
            if let Some(end) = inner.find("</span>") {
                let actual = inner[..end].trim();
                assert_eq!(
                    actual, expected,
                    "transaction status mismatch on detail page"
                );
                return;
            }
        }
    }
    panic!("could not parse status from detail page snippet");
}

#[then("the Post button should not be visible")]
async fn then_post_not_visible(world: &mut UiWorld) {
    let content = current_page_content(world).await;
    assert!(
        !content.contains("/post\""),
        "did not expect Post form on this detail page; snippet: {}",
        &content[..content.len().min(400)]
    );
}

#[then("the Void button should not be visible")]
async fn then_void_not_visible(world: &mut UiWorld) {
    let content = current_page_content(world).await;
    assert!(
        !content.contains("/void\""),
        "did not expect Void form on this detail page; snippet: {}",
        &content[..content.len().min(400)]
    );
}

use cucumber::{then, when};

use crate::PbaWorld;

#[when("I list all transactions")]
async fn list_all_transactions(world: &mut PbaWorld) {
    let result = world
        .client
        .list_all_transactions()
        .send()
        .await
        .expect("Failed to list all transactions");

    world.all_transactions_total = Some(result.total());
    world.all_transactions_count = Some(result.transactions().len());
    world.all_transactions_types = Some(
        result
            .transactions()
            .iter()
            .map(|t| t.r#type().to_string())
            .collect(),
    );
    world.all_transactions_account_ids = Some(
        result
            .transactions()
            .iter()
            .map(|t| t.account_id().to_string())
            .collect(),
    );
    world.all_transactions_funding_types = Some(
        result
            .transactions()
            .iter()
            .map(|t| t.funding_type().map(|s| s.to_string()))
            .collect(),
    );
}

#[when(regex = r"^I list all transactions with limit (\d+)$")]
async fn list_all_transactions_with_limit(world: &mut PbaWorld, limit: i64) {
    let result = world
        .client
        .list_all_transactions()
        .limit(limit)
        .send()
        .await
        .expect("Failed to list all transactions with limit");

    world.all_transactions_total = Some(result.total());
    world.all_transactions_count = Some(result.transactions().len());
    world.all_transactions_types = Some(
        result
            .transactions()
            .iter()
            .map(|t| t.r#type().to_string())
            .collect(),
    );
    world.all_transactions_account_ids = Some(
        result
            .transactions()
            .iter()
            .map(|t| t.account_id().to_string())
            .collect(),
    );
    world.all_transactions_funding_types = Some(
        result
            .transactions()
            .iter()
            .map(|t| t.funding_type().map(|s| s.to_string()))
            .collect(),
    );
}

#[then(regex = r"^the total transaction count should be (\d+)$")]
async fn total_transaction_count(world: &mut PbaWorld, expected: i64) {
    let total = world
        .all_transactions_total
        .expect("No all-transactions result");
    assert_eq!(total, expected, "Expected total {expected}, got {total}");
}

#[then(regex = r"^the total transaction count should be at least (\d+)$")]
async fn total_transaction_count_at_least(world: &mut PbaWorld, min: i64) {
    let total = world
        .all_transactions_total
        .expect("No all-transactions result");
    assert!(
        total >= min,
        "Expected at least {min} transactions, got {total}"
    );
}

#[then("the transactions list should be empty")]
async fn transactions_list_empty(world: &mut PbaWorld) {
    let count = world
        .all_transactions_count
        .expect("No all-transactions result");
    assert_eq!(count, 0, "Expected empty list, got {count} entries");
}

#[then("the transactions list should contain the current account")]
async fn transactions_contain_current_account(world: &mut PbaWorld) {
    let account_id = world.account_id.as_ref().expect("No account ID set");
    let ids = world
        .all_transactions_account_ids
        .as_ref()
        .expect("No all-transactions result");
    assert!(
        ids.iter().any(|id| id == account_id),
        "Expected transaction for account '{account_id}', got: {ids:?}"
    );
}

#[then(regex = r#"^the transactions list should contain a "([^"]*)" transaction$"#)]
async fn transactions_contain_type(world: &mut PbaWorld, expected_type: String) {
    let types = world
        .all_transactions_types
        .as_ref()
        .expect("No all-transactions result");
    assert!(
        types.iter().any(|t| t == &expected_type),
        "Expected a '{expected_type}' transaction, got types: {types:?}"
    );
}

#[then(regex = r"^the transactions list should have (\d+) entries$")]
async fn transactions_list_count(world: &mut PbaWorld, expected: usize) {
    let count = world
        .all_transactions_count
        .expect("No all-transactions result");
    assert_eq!(count, expected, "Expected {expected} entries, got {count}");
}

#[then(regex = r#"^the transactions list should contain a funding type "([^"]*)"$"#)]
async fn transactions_contain_funding_type(world: &mut PbaWorld, expected_type: String) {
    let types = world
        .all_transactions_funding_types
        .as_ref()
        .expect("No all-transactions result");
    assert!(
        types
            .iter()
            .any(|t| t.as_deref() == Some(expected_type.as_str())),
        "Expected a funding type '{expected_type}', got: {types:?}"
    );
}

$version: "2"
namespace com.ppi.pba

/// List transactions for a purpose-bound account with offset/limit pagination.
@readonly
@http(method: "GET", uri: "/pb-accounts/{account_id}/transactions")
operation ListPBAccountTransactions {
    input := {
        @required
        @httpLabel
        account_id: String

        @httpQuery("offset")
        offset: Long

        @httpQuery("limit")
        limit: Long

        @httpQuery("from_date")
        from_date: DateTime

        @httpQuery("to_date")
        to_date: DateTime
    }
    output := {
        @required
        transactions: TransactionList

        @required
        total: Long

        @required
        offset: Long

        @required
        limit: Long
    }
    errors: [AccountNotFoundError]
}

@deprecated(message: "Use ListPBAccountTransactions.", since: "2026-05-08")
@readonly
@http(method: "GET", uri: "/accounts/{account_id}/transactions")
operation ListTransactions {
    input := {
        @required
        @httpLabel
        account_id: String

        @httpQuery("offset")
        offset: Long

        @httpQuery("limit")
        limit: Long

        @httpQuery("from_date")
        from_date: DateTime

        @httpQuery("to_date")
        to_date: DateTime
    }
    output := {
        @required
        transactions: TransactionList

        @required
        total: Long

        @required
        offset: Long

        @required
        limit: Long
    }
    errors: [AccountNotFoundError]
}

/// List all transactions across all accounts with offset/limit pagination.
@readonly
@http(method: "GET", uri: "/transactions")
operation ListAllTransactions {
    input := {
        @httpQuery("offset")
        offset: Long

        @httpQuery("limit")
        limit: Long

        @httpQuery("from_date")
        from_date: DateTime

        @httpQuery("to_date")
        to_date: DateTime
    }
    output := {
        @required
        transactions: TransactionList

        @required
        total: Long

        @required
        offset: Long

        @required
        limit: Long
    }
}

list TransactionList {
    member: TransactionSummary
}

structure TransactionSummary {
    @required
    id: String

    @required
    account_id: String

    @required
    account_kind: String

    @required
    type: TransactionType

    @required
    status: TransactionStatus

    @required
    amount: Money

    pool: PoolType

    @required
    direction: TransactionDirection

    description: String
    merchant_id: String
    merchant_mcc: String
    source_ifsc: String
    source_account: String
    gateway_ref: String
    funding_type: String
    correlation_id: String

    @required
    created_at: DateTime
}

use cucumber::{then, when};
use futures::future::join_all;

use crate::PbaWorld;

#[when(regex = r#"^I pay (\d+) to merchant "([^"]*)" with MCC "([^"]*)" described as "([^"]*)"$"#)]
async fn make_payment(
    world: &mut PbaWorld,
    amount: i64,
    merchant_id: String,
    mcc: String,
    description: String,
) {
    let account_id = world.account_id.as_ref().expect("No account ID");
    let result = world
        .client
        .make_payment()
        .account_id(account_id)
        .amount(amount)
        .merchant_mcc(&mcc)
        .merchant_id(&merchant_id)
        .description(&description)
        .send()
        .await;
    match result {
        Ok(output) => {
            world.last_payment = Some(crate::PaymentResult {
                payment_id: output.payment_id().to_string(),
                amount: output.amount(),
                from_others: output.from_others(),
                from_self: output.from_self(),
            });
            world.last_error = None;
        }
        Err(e) => panic!("Payment failed unexpectedly: {e:?}"),
    }
}

#[when(
    regex = r#"^I attempt to pay (\d+) to merchant "([^"]*)" with MCC "([^"]*)" described as "([^"]*)"$"#
)]
async fn attempt_payment(
    world: &mut PbaWorld,
    amount: i64,
    merchant_id: String,
    mcc: String,
    description: String,
) {
    let account_id = world.account_id.as_ref().expect("No account ID");
    let result = world
        .client
        .make_payment()
        .account_id(account_id)
        .amount(amount)
        .merchant_mcc(&mcc)
        .merchant_id(&merchant_id)
        .description(&description)
        .send()
        .await;
    match result {
        Ok(output) => {
            world.last_payment = Some(crate::PaymentResult {
                payment_id: output.payment_id().to_string(),
                amount: output.amount(),
                from_others: output.from_others(),
                from_self: output.from_self(),
            });
            world.last_error = None;
        }
        Err(e) => {
            let err_str = format!("{e:?}");
            let kind = if err_str.contains("AccountNotActive") || err_str.contains("409") {
                "account_not_active"
            } else if err_str.contains("InvalidMcc") {
                "invalid_mcc"
            } else if err_str.contains("InsufficientFunds") {
                "insufficient_funds"
            } else if err_str.contains("422") {
                "insufficient_funds"
            } else {
                "unknown"
            };
            world.last_error = Some(crate::PbaError {
                kind: kind.to_string(),
                message: None,
            });
        }
    }
}

#[when(
    regex = r#"^I pay (\d+) to merchant "([^"]*)" with MCC "([^"]*)" described as "([^"]*)" with gateway ref "([^"]*)"$"#
)]
async fn make_payment_with_gateway_ref(
    world: &mut PbaWorld,
    amount: i64,
    merchant_id: String,
    mcc: String,
    description: String,
    gateway_ref: String,
) {
    let account_id = world.account_id.as_ref().expect("No account ID");
    let result = world
        .client
        .make_payment()
        .account_id(account_id)
        .amount(amount)
        .merchant_mcc(&mcc)
        .merchant_id(&merchant_id)
        .description(&description)
        .gateway_ref(&gateway_ref)
        .send()
        .await;
    match result {
        Ok(output) => {
            world.last_payment = Some(crate::PaymentResult {
                payment_id: output.payment_id().to_string(),
                amount: output.amount(),
                from_others: output.from_others(),
                from_self: output.from_self(),
            });
            world.last_payment_gateway_ref = output.gateway_ref().map(|s| s.to_string());
            world.last_error = None;
        }
        Err(e) => panic!("Payment failed unexpectedly: {e:?}"),
    }
}

#[then(regex = r#"^the payment response should echo gateway ref "([^"]*)"$"#)]
async fn payment_echoes_gateway_ref(world: &mut PbaWorld, expected: String) {
    let actual = world
        .last_payment_gateway_ref
        .as_deref()
        .expect("No gateway_ref captured from last payment response");
    assert_eq!(
        actual, expected,
        "Gateway ref mismatch: response echoed `{}`, expected `{}`",
        actual, expected
    );
}

#[then("the payment should succeed")]
async fn payment_should_succeed(world: &mut PbaWorld) {
    assert!(
        world.last_payment.is_some(),
        "Expected payment to succeed, but no payment result"
    );
}

#[then(regex = r"^(\d+) should come from others-pool$")]
async fn from_others(world: &mut PbaWorld, expected: i64) {
    let payment = world.last_payment.as_ref().expect("No payment result");
    assert_eq!(
        payment.from_others, expected,
        "Others-pool contribution mismatch"
    );
}

#[then(regex = r"^(\d+) should come from self-pool$")]
async fn from_self(world: &mut PbaWorld, expected: i64) {
    let payment = world.last_payment.as_ref().expect("No payment result");
    assert_eq!(
        payment.from_self, expected,
        "Self-pool contribution mismatch"
    );
}

#[then("the payment should be rejected as insufficient funds")]
async fn payment_rejected_insufficient(world: &mut PbaWorld) {
    let err = world
        .last_error
        .as_ref()
        .expect("Expected an error but got success (last_error is None)");
    assert_eq!(
        err.kind, "insufficient_funds",
        "Expected insufficient_funds but got: {}",
        err.kind
    );
}

#[then("the payment should be rejected as invalid MCC")]
async fn payment_rejected_invalid_mcc(world: &mut PbaWorld) {
    let err = world.last_error.as_ref().expect("Expected an error");
    assert_eq!(err.kind, "invalid_mcc");
}

#[then("the payment should be rejected as account not active")]
async fn payment_rejected_not_active(world: &mut PbaWorld) {
    let err = world
